func (q *Queries) MarkProviderIntentSucceeded(ctx context.Context, arg MarkProviderIntentSucceededParams) (int64, error) {
	result, err := q.db.Exec(ctx, markProviderIntentSucceeded, arg.Now, arg.ResultEvidence, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const markProviderIntentSuperseded = `-- name: MarkProviderIntentSuperseded :execrows
UPDATE openrails.provider_intents
SET status = 'superseded',
    last_failure_reason = $1,
    claimed_until = NULL,
    updated_at = now()
WHERE id = $2 AND status IN ('pending', 'in_flight', 'failed_retryable', 'unknown_needs_verify')
`

type MarkProviderIntentSupersededParams struct {
	Reason *string
	ID     uuid.UUID
}

